public sealed class DbHistoryProvider(IMessageDb db) : ChatHistoryProvider
{
    private readonly ProviderSessionState<State> _state = new(
        _ => new State { Key = Guid.NewGuid().ToString() }, nameof(DbHistoryProvider));
    public override string StateKey => _state.StateKey;

    protected override async ValueTask<IEnumerable<ChatMessage>> ProvideChatHistoryAsync(
        InvokingContext ctx, CancellationToken ct = default)
        => await db.LoadAsync(_state.GetOrInitializeState(ctx.Session).Key, ct);

    protected override async ValueTask StoreChatHistoryAsync(
        InvokedContext ctx, CancellationToken ct = default)
    {
        var s = _state.GetOrInitializeState(ctx.Session);
        _state.SaveState(ctx.Session, s);
        await db.AppendAsync(s.Key, ctx.RequestMessages.Concat(ctx.ResponseMessages ?? []), ct);
    }
    public sealed class State { public string? Key { get; set; } }
}
